Exception bigObjectEx = new BigObjectException('big object message');
System.assertEquals('big object message', bigObjectEx.getMessage());
System.assertEquals('System.BigObjectException', bigObjectEx.getTypeName());
System.assertEquals(1, bigObjectEx.getLineNumber());
System.assertEquals('AnonymousBlock: line 1, column 1', bigObjectEx.getStackTraceString());
String bigObjectFieldsError = '';
try { bigObjectEx.getInaccessibleFields(); } catch (TypeException e) { bigObjectFieldsError = e.getMessage(); }
System.assertEquals('Procedure is only valid for System.QueryException', bigObjectFieldsError);
bigObjectEx.setMessage('changed big object');
System.assertEquals('changed big object', bigObjectEx.getMessage());
bigObjectEx.initCause(new DmlException('big object cause'));
System.assertEquals('big object cause', bigObjectEx.getCause().getMessage());
